/**
 * Links each automated test to its row in the master workbook.
 *
 * qa/test-cases/suites.json is generated by `pnpm qa:cases` from the same data as the workbook,
 * so a test's title and suite tags always match the manual case:
 *
 *   const c = mf('MF-EXP-001');
 *   test(c.title, c.details, async ({ page }) => { ... });
 *
 * Tags: @smoke @sanity @happy @regression · @p1/@p2/@p3 · @area-<sanity-area>
 */
import suites from '../../../../test-cases/suites.json';

type CaseMeta = { title: string; priority: string; area: string; suites: string[] };
const CASES = suites as Record<string, CaseMeta>;

const SUITE_TAG: Record<string, string> = {
  Smoke: '@smoke', Sanity: '@sanity', 'Happy Path': '@happy', Regression: '@regression',
};

const slug = (s: string) => s.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

export function mf(id: string): { title: string; details: { tag: string[]; annotation: { type: string; description: string }[] } } {
  const c = CASES[id];
  if (!c) throw new Error(`${id} is not in qa/test-cases/suites.json — add it to qa/tools/tc_data.py and run pnpm qa:cases`);
  return {
    title: `${id} ${c.title}`,
    details: {
      tag: [...c.suites.map((s) => SUITE_TAG[s]), `@${c.priority.toLowerCase()}`, `@area-${slug(c.area)}`],
      annotation: [{ type: 'workbook', description: `qa/test-cases/FinTrack-BD_Test-Cases.xlsx → ${id}` }],
    },
  };
}
